using BabyRoutine.Domain.Common;
using BabyRoutine.Domain.Exceptions;

namespace BabyRoutine.Domain.Events;

/// <summary>
/// A logged baby event. The id is generated by the client so offline writes can be replayed idempotently.
/// <see cref="EndedAt"/> is <c>null</c> while the event is running. Deletes are soft (<see cref="DeletedAt"/>)
/// and every change bumps <see cref="UpdatedAt"/> (server receive time) so delta sync picks it up. Conflicts between
/// clients are decided on <see cref="ClientUpdatedAt"/> (the client's edit time), never on the server receive time.
/// All timestamps are UTC truncated to microseconds.
/// </summary>
public sealed class Event
{
    public const int NotesMaxLength = 2000;

    /// <summary>How far ahead of the server clock a client edit time is trusted; later times are clamped to the server time.</summary>
    public static readonly TimeSpan MaxClientClockSkew = ClientEditTime.MaxFutureSkew;

    private Event()
    {
    }

    private Event(Guid id, Guid babyId, Guid typeId, Guid createdBy, DateTimeOffset createdAt, DateTimeOffset clientUpdatedAt)
    {
        Id = id;
        BabyId = babyId;
        TypeId = typeId;
        CreatedBy = createdBy;
        CreatedAt = createdAt;
        UpdatedAt = createdAt;
        ClientUpdatedAt = clientUpdatedAt;
    }

    public Guid Id { get; private set; }

    public Guid BabyId { get; private set; }

    public Guid TypeId { get; private set; }

    public DateTimeOffset StartedAt { get; private set; }

    public DateTimeOffset? EndedAt { get; private set; }

    public EventPayload Payload { get; private set; } = EventPayload.Empty;

    public string? Notes { get; private set; }

    public Guid CreatedBy { get; private set; }

    public DateTimeOffset CreatedAt { get; private set; }

    /// <summary>Server receive time of the last change; the delta-sync cursor.</summary>
    public DateTimeOffset UpdatedAt { get; private set; }

    /// <summary>
    /// Client edit time of the last applied change, bounded by <see cref="MaxClientClockSkew"/>; the server time when
    /// the client sent none, and for server-side changes such as deletes. Last write wins compares incoming client
    /// times with this value.
    /// </summary>
    public DateTimeOffset ClientUpdatedAt { get; private set; }

    public DateTimeOffset? DeletedAt { get; private set; }

    public bool IsDeleted => DeletedAt is not null;

    public bool IsRunning => EndedAt is null && !IsDeleted;

    public TimeSpan? Duration => EndedAt - StartedAt;

    /// <summary>
    /// Creates an event received at <paramref name="now"/> (its <see cref="CreatedAt"/> and <see cref="UpdatedAt"/>).
    /// <see cref="ClientUpdatedAt"/> is the bounded <paramref name="clientUpdatedAt"/>, or <paramref name="now"/> when absent.
    /// </summary>
    public static Event Create(
        Guid id,
        Guid babyId,
        Guid typeId,
        Guid createdBy,
        DateTimeOffset startedAt,
        DateTimeOffset? endedAt,
        EventPayload payload,
        string? notes,
        DateTimeOffset now,
        DateTimeOffset? clientUpdatedAt = null)
    {
        var created = new Event(
            Ids.Required(id, nameof(id)),
            Ids.Required(babyId, nameof(babyId)),
            Ids.Required(typeId, nameof(typeId)),
            Ids.Required(createdBy, nameof(createdBy)),
            UtcTime.Normalize(now),
            ClientEditTime.Bound(clientUpdatedAt, now));
        created.ApplyDetails(ValidateDetails(typeId, startedAt, endedAt, payload, notes));
        return created;
    }

    /// <summary>
    /// Replaces the editable details, as for an idempotent upsert of an existing event. When the details equal the
    /// stored ones (payload compared as JSON values) nothing changes, not even <see cref="UpdatedAt"/> or
    /// <see cref="ClientUpdatedAt"/>, so a replayed upsert returns the same representation. Otherwise
    /// <see cref="UpdatedAt"/> becomes <paramref name="now"/> and <see cref="ClientUpdatedAt"/> the bounded
    /// <paramref name="clientUpdatedAt"/> (<paramref name="now"/> when absent).
    /// </summary>
    public void Edit(
        Guid typeId,
        DateTimeOffset startedAt,
        DateTimeOffset? endedAt,
        EventPayload payload,
        string? notes,
        DateTimeOffset now,
        DateTimeOffset? clientUpdatedAt = null)
    {
        EnsureNotDeleted();
        var details = ValidateDetails(typeId, startedAt, endedAt, payload, notes);
        if (Matches(details))
        {
            return;
        }

        ApplyDetails(details);
        Touch(now, ClientEditTime.Bound(clientUpdatedAt, now));
    }

    /// <summary>
    /// Decides how a client upsert applies to this stored event, before any change is made:
    /// an event never moves to another baby (<see cref="EventBabyMismatchException"/>); a deleted event stays deleted
    /// (<see cref="EventUpsertDecision.IgnoreDeleted"/>); a write whose client <paramref name="clientUpdatedAt"/>
    /// (bounded by <see cref="MaxClientClockSkew"/> ahead of <paramref name="now"/>) is strictly older than the stored
    /// <see cref="ClientUpdatedAt"/> loses (last write wins, <see cref="EventUpsertDecision.IgnoreStale"/>).
    /// Without a client timestamp, or on a tie, the incoming write is applied.
    /// </summary>
    public EventUpsertDecision DecideUpsert(Guid babyId, DateTimeOffset? clientUpdatedAt, DateTimeOffset now)
    {
        EnsureBelongsTo(babyId);
        return this switch
        {
            { IsDeleted: true } => EventUpsertDecision.IgnoreDeleted,
            _ when IsNewerThan(clientUpdatedAt, now) => EventUpsertDecision.IgnoreStale,
            _ => EventUpsertDecision.Apply,
        };
    }

    /// <summary>
    /// Whether an edit to these details must have its payload checked against the type's fields: when the type or the
    /// payload (compared as JSON values) changes, or a running event is being completed. A payload stored before the
    /// field rules existed stays editable (times, notes) as long as it is sent back unchanged.
    /// </summary>
    public bool NeedsPayloadCheck(Guid typeId, EventPayload payload, DateTimeOffset? endedAt) =>
        TypeId != typeId
        || !Payload.IsEquivalentTo(payload)
        || (EndedAt is null && endedAt is not null);

    /// <summary>Ends a running event; a server-side change, so <see cref="ClientUpdatedAt"/> becomes <paramref name="now"/> too.</summary>
    public void Stop(DateTimeOffset endedAt, DateTimeOffset now)
    {
        EnsureNotDeleted();
        EnsureRunning();
        EndedAt = EnsureValidRange(StartedAt, UtcTime.Normalize(endedAt));
        Touch(now, UtcTime.Normalize(now));
    }

    /// <summary>
    /// Marks the event deleted; a delete always wins, whatever the client times. <see cref="UpdatedAt"/> and
    /// <see cref="ClientUpdatedAt"/> become the deletion time. Repeating it is a no-op so retried deletes stay idempotent.
    /// </summary>
    public void SoftDelete(DateTimeOffset now)
    {
        if (IsDeleted)
        {
            return;
        }

        DeletedAt = UtcTime.Normalize(now);
        Touch(DeletedAt.Value, DeletedAt.Value);
    }

    private static EventDetails ValidateDetails(Guid typeId, DateTimeOffset startedAt, DateTimeOffset? endedAt, EventPayload payload, string? notes)
    {
        var normalizedStart = UtcTime.Normalize(startedAt);
        return new EventDetails(
            Ids.Required(typeId, nameof(typeId)),
            normalizedStart,
            EnsureValidRange(normalizedStart, UtcTime.Normalize(endedAt)),
            payload,
            Text.Optional(notes, nameof(Notes), NotesMaxLength));
    }

    private void ApplyDetails(EventDetails details)
    {
        TypeId = details.TypeId;
        StartedAt = details.StartedAt;
        EndedAt = details.EndedAt;
        Payload = details.Payload;
        Notes = details.Notes;
    }

    private bool Matches(EventDetails details) =>
        TypeId == details.TypeId
        && StartedAt == details.StartedAt
        && EndedAt == details.EndedAt
        && string.Equals(Notes, details.Notes, StringComparison.Ordinal)
        && Payload.IsEquivalentTo(details.Payload);

    private bool IsNewerThan(DateTimeOffset? clientUpdatedAt, DateTimeOffset now) =>
        clientUpdatedAt is not null && ClientEditTime.Bound(clientUpdatedAt, now) < ClientUpdatedAt;

    private void EnsureBelongsTo(Guid babyId)
    {
        if (BabyId != babyId)
        {
            throw new EventBabyMismatchException(Id, babyId);
        }
    }

    private void Touch(DateTimeOffset now, DateTimeOffset clientUpdatedAt)
    {
        UpdatedAt = UtcTime.Normalize(now);
        ClientUpdatedAt = clientUpdatedAt;
    }

    private void EnsureNotDeleted()
    {
        if (IsDeleted)
        {
            throw new EventDeletedException(Id);
        }
    }

    private void EnsureRunning()
    {
        if (EndedAt is not null)
        {
            throw new EventAlreadyStoppedException(Id);
        }
    }

    private static DateTimeOffset? EnsureValidRange(DateTimeOffset startedAt, DateTimeOffset? endedAt) =>
        endedAt is null || endedAt.Value >= startedAt
            ? endedAt
            : throw new InvalidEventTimeRangeException(startedAt, endedAt.Value);

    private static DateTimeOffset EnsureValidRange(DateTimeOffset startedAt, DateTimeOffset endedAt) =>
        endedAt >= startedAt ? endedAt : throw new InvalidEventTimeRangeException(startedAt, endedAt);

    private readonly record struct EventDetails(Guid TypeId, DateTimeOffset StartedAt, DateTimeOffset? EndedAt, EventPayload Payload, string? Notes);
}
